"use client";

import { useEffect, useRef, useState, useCallback } from "react";
import { motion, useSpring, useMotionValue, useTransform, AnimatePresence } from "framer-motion";
import useMousePosition from "../hooks/useMousePosition";

type CursorVariant = "default" | "link" | "button" | "text" | "magnetic";

interface CursorState {
  variant: CursorVariant;
  label: string;
  magnetic: boolean;
  target: Element | null;
}

const SPRING_CONFIG = { damping: 28, stiffness: 380, mass: 0.6 };
const MAGNETIC_SPRING_CONFIG = { damping: 32, stiffness: 280, mass: 0.8 };

export default function CustomCursor() {
  const [isVisible, setIsVisible] = useState(false);
  const [isTouch, setIsTouch] = useState(true); // default true, set false on mousemove
  const [cursorState, setCursorState] = useState<CursorState>({
    variant: "default",
    label: "",
    magnetic: false,
    target: null,
  });

  const mouse = useMousePosition();
  const cursorX = useMotionValue(0);
  const cursorY = useMotionValue(0);

  const smoothX = useSpring(cursorX, SPRING_CONFIG);
  const smoothY = useSpring(cursorY, SPRING_CONFIG);

  // Magnetic spring (separate for snappier feel)
  const magX = useMotionValue(0);
  const magY = useMotionValue(0);
  const smoothMagX = useSpring(magX, MAGNETIC_SPRING_CONFIG);
  const smoothMagY = useSpring(magY, MAGNETIC_SPRING_CONFIG);

  // Detect touch vs mouse
  useEffect(() => {
    const detectMouse = () => setIsTouch(false);
    const detectTouch = () => setIsTouch(true);

    window.addEventListener("mousemove", detectMouse, { once: true, passive: true });
    window.addEventListener("touchstart", detectTouch, { once: true, passive: true });

    return () => {
      window.removeEventListener("mousemove", detectMouse);
      window.removeEventListener("touchstart", detectTouch);
    };
  }, []);

  // Update cursor position from mouse
  useEffect(() => {
    if (!isVisible && mouse.x > 0 && mouse.y > 0) {
      setIsVisible(true);
    }

    let targetX = mouse.x;
    let targetY = mouse.y;

    if (cursorState.magnetic && cursorState.target) {
      const rect = cursorState.target.getBoundingClientRect();
      targetX = rect.left + rect.width / 2;
      targetY = rect.top + rect.height / 2;
    }

    cursorX.set(targetX);
    cursorY.set(targetY);

    // Magnetic offset for inner elements if needed
    magX.set(targetX);
    magY.set(targetY);
  }, [mouse, cursorState, cursorX, cursorY, magX, magY, isVisible]);

  // Hover detection
  useEffect(() => {
    const handleMouseOver = (e: MouseEvent) => {
      const target = e.target as HTMLElement;
      const cursorTarget = target.closest("[data-cursor]") as HTMLElement | null;

      if (cursorTarget) {
        const variant = (cursorTarget.dataset.cursor as CursorVariant) || "default";
        const label = cursorTarget.dataset.cursorLabel || "";
        const magnetic = cursorTarget.dataset.cursorMagnetic === "true" || variant === "magnetic";

        setCursorState({
          variant,
          label,
          magnetic,
          target: magnetic ? cursorTarget : null,
        });
      }
    };

    const handleMouseOut = (e: MouseEvent) => {
      const target = e.target as HTMLElement;
      const cursorTarget = target.closest("[data-cursor]");

      if (cursorTarget) {
        setCursorState({
          variant: "default",
          label: "",
          magnetic: false,
          target: null,
        });
      }
    };

    document.addEventListener("mouseover", handleMouseOver, { passive: true });
    document.addEventListener("mouseout", handleMouseOut, { passive: true });

    return () => {
      document.removeEventListener("mouseover", handleMouseOver);
      document.removeEventListener("mouseout", handleMouseOut);
    };
  }, []);

  // Hide on mouse leave window
  useEffect(() => {
    const handleMouseLeave = () => setIsVisible(false);
    const handleMouseEnter = () => setIsVisible(true);

    document.body.addEventListener("mouseleave", handleMouseLeave);
    document.body.addEventListener("mouseenter", handleMouseEnter);

    return () => {
      document.body.removeEventListener("mouseleave", handleMouseLeave);
      document.body.removeEventListener("mouseenter", handleMouseEnter);
    };
  }, []);

  if (isTouch) return null;

  const variants = {
    default: { width: 16, height: 16, borderRadius: "50%" },
    link: { width: 48, height: 48, borderRadius: "50%" },
    button: { width: 80, height: 80, borderRadius: "50%" },
    text: { width: 120, height: 120, borderRadius: "50%" },
    magnetic: { width: 100, height: 100, borderRadius: "50%" },
  };

  const currentVariant = variants[cursorState.variant] || variants.default;

  return (
    <>
      {/* Main cursor ring */}
      <motion.div
        className="custom-cursor-ring pointer-events-none fixed top-0 left-0 z-[9998] flex items-center justify-center mix-blend-difference"
        style={{
          x: smoothX,
          y: smoothY,
          translateX: "-50%",
          translateY: "-50%",
          willChange: "transform",
        }}
        animate={{
          width: currentVariant.width,
          height: currentVariant.height,
          borderRadius: currentVariant.borderRadius,
          opacity: isVisible ? 1 : 0,
        }}
        transition={{ type: "spring", damping: 24, stiffness: 300, mass: 0.5 }}
      >
        <span className="custom-cursor-label pointer-events-none text-[10px] font-mono uppercase tracking-widest text-white opacity-0 transition-opacity duration-200">
          {cursorState.label}
        </span>
        <motion.div
          className="absolute inset-0 rounded-full border border-white/80"
          animate={{ scale: cursorState.magnetic ? 1.15 : 1 }}
          transition={{ type: "spring", damping: 20, stiffness: 300 }}
        />
      </motion.div>

      {/* Inner dot */}
      <motion.div
        className="custom-cursor-dot pointer-events-none fixed top-0 left-0 z-[9998] rounded-full bg-white mix-blend-difference"
        style={{
          x: smoothMagX,
          y: smoothMagY,
          translateX: "-50%",
          translateY: "-50%",
          willChange: "transform",
        }}
        animate={{
          width: cursorState.variant === "default" ? 6 : 0,
          height: cursorState.variant === "default" ? 6 : 0,
          opacity: isVisible ? 1 : 0,
        }}
        transition={{ type: "spring", damping: 28, stiffness: 400, mass: 0.4 }}
      />
    </>
  );
}
