/* Hide on mobile */
@media (max-width: 768px) {
  .hide-mobile {
    display: none !important;
  }
}

/* --------------------------------------------------------------------------
   Custom cursor system
   -------------------------------------------------------------------------- */

@media (hover: hover) and (pointer: fine) {
  html.has-custom-cursor,
  html.has-custom-cursor * {
    cursor: none !important;
  }
}

/* Ensure the morphing ring inherits border radius during animation. */
.rounded-inherit {
  border-radius: inherit;
}

/* Respect reduced motion: if the user prefers reduced motion, the cursor
   component unmounts itself; this rule is a safety net. */
@media (prefers-reduced-motion: reduce) {
  html.has-custom-cursor,
  html.has-custom-cursor * {
    cursor: auto !important;
  }
}

/* Cursor-safe elements: keep the default cursor for text selection and inputs
   even when the custom cursor is active. Add this class where needed. */
html.has-custom-cursor .cursor-default,
html.has-custom-cursor .cursor-default * {
  cursor: text !important;
}

